mapper.update:
UPDATE reviews
   SET rating = #{rating},
       content = #{content},
       images = #{images}
 WHERE id = #{id}

mapper.select:
SELECT FROM reviews r JOIN users u ON u.id = r.user_id JOIN contractors c ON c.id = r.contractor_id
AND (u.nickname LIKE CONCAT('%', #{keyword}, '%') OR c.company_name LIKE CONCAT('%', #{keyword}, '%') OR r.content LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY r.created_at DESC LIMIT #{limit} OFFSET #{offset}
